import marshal
src = open('dateutil/parser.py','rb').read()
code_new = compile(src, 'dateutil/parser.py', 'exec')
f=open('dateutil/__pycache__/parser.cpython-36.pyc','rb'); f.read(12)
code_old = marshal.load(f)

def cmp(a, b, path=""):
    p = path + "/" + a.co_name
    for attr in ('co_name','co_argcount','co_kwonlyargcount','co_nlocals','co_stacksize','co_flags','co_code','co_consts','co_names','co_varnames','co_freevars','co_cellvars','co_filename'):
        if getattr(a,attr) != getattr(b,attr):
            if attr == 'co_consts':
                # recurse
                for i,(x,y) in enumerate(zip(a.co_consts,b.co_consts)):
                    if x!=y:
                        if hasattr(x,'co_name') and hasattr(y,'co_name'):
                            cmp(x,y,p)
                        else:
                            print("CONST DIFF", p, i, repr(x)[:120], "||", repr(y)[:120])
            elif attr == 'co_filename':
                pass
            else:
                print("ATTR DIFF", p, attr, getattr(a,attr), getattr(b,attr))
    # line numbers
    if a.co_firstlineno != b.co_firstlineno:
        print("LINENO", p, a.co_firstlineno, b.co_firstlineno)
    if a.co_lnotab != b.co_lnotab:
        print("LNOTAB DIFF", p, a.co_lnotab, b.co_lnotab)
cmp(code_old, code_new)
